// The authoring half of block references: giving the block under the cursor
// an identifier so it can be linked to.
//
// Nobody types `^a3f9c1` by hand — in Obsidian the id is generated by "Copy
// link to block", and the syntax is only ever read afterwards. Without this
// Clew could follow other people's block references but never make one.
//
// The rules for WHERE the marker goes are the mirror image of how block-refs.js
// reads them, and the definition of a legal id is imported from there rather
// than restated, so the writer and the reader cannot drift apart.
import { ID, boundaries } from '../../engine/block-refs.js';

const LIST_ITEM = /^[ \t]*(?:[-*+]|\d+[.)])[ \t]+/;
const FENCE = /^[ \t]*(?:`{3,}|~{3,})/;
const MARKER_LINE = new RegExp(`^[ \\t]*\\^(${ID})[ \\t]*$`);
const TRAILING_MARKER = new RegExp(`[ \\t]\\^(${ID})[ \\t]*$`);

/** Six lowercase alphanumerics, as Obsidian generates. */
export function generateBlockId(random = Math.random) {
	const alphabet = 'abcdefghijklmnopqrstuvwxyz0123456789';
	let id = '';
	for (let i = 0; i < 6; i++) id += alphabet[Math.floor(random() * alphabet.length)];
	return id;
}

/**
 * Work out the block reference for the cursor's block.
 *
 * Returns `{ id, insert }` where `insert` is null if the block already carries
 * a marker (ids are stable — re-running the command on the same block must
 * hand back the same link, not litter the note with duplicates), otherwise
 * `{ line, column, text }` describing a single-point insertion, with `line`
 * 0-based. Returns null when the cursor is not in a block at all.
 *
 * A table or a fenced block cannot carry a trailing word, so their marker goes
 * on a line of its own beneath — the form block-refs.js reads as "the block
 * above". Everything else takes ` ^id` at the end: on the cursor's own list
 * item when in a list, otherwise on the block's last line.
 */
export function blockRefEdit(lines, lineNo, makeId = generateBlockId) {
	if (lineNo < 0 || lineNo >= lines.length) return null;
	const blank = boundaries(lines);
	if (blank[lineNo]) return null;

	let start = lineNo;
	let end = lineNo;
	while (start > 0 && !blank[start - 1]) start--;
	while (end + 1 < lines.length && !blank[end + 1]) end++;

	// Already marked? A marker written beneath a table or a fence has no blank
	// line above it, so it is the block's own last line — checked before the
	// line below, or the command would issue a second id every time it ran on
	// a table it had already named.
	const own = MARKER_LINE.exec(lines[end]);
	if (own) return { id: own[1], insert: null };
	const existingTrailing = TRAILING_MARKER.exec(lines[end]);
	if (existingTrailing) return { id: existingTrailing[1], insert: null };
	const beneath = MARKER_LINE.exec(lines[end + 1] ?? '');
	if (beneath) return { id: beneath[1], insert: null };
	// In a list, the marker belongs to the cursor's own item.
	const ownItem = TRAILING_MARKER.exec(lines[lineNo]);
	if (ownItem) return { id: ownItem[1], insert: null };

	const id = makeId();
	const body = lines.slice(start, end + 1);
	const isTable = body.some((line) => line.includes('|'));
	const isFenced = body.some((line) => FENCE.test(line));
	if (isTable || isFenced) {
		return { id, insert: { line: end, column: lines[end].length, text: `\n^${id}` } };
	}
	const target = LIST_ITEM.test(lines[lineNo]) ? lineNo : end;
	return { id, insert: { line: target, column: lines[target].length, text: ` ^${id}` } };
}

/**
 * `[[Note#^id]]` — the text that gets copied.
 *
 * `resolve` is the vault's name resolver. The bare basename is preferred, as
 * Obsidian writes it, but only when the vault agrees it points back at this
 * note; where two folders hold notes of the same name the full path is the
 * only link that means what it says.
 */
export function blockRefLink(path, id, resolve = () => path) {
	const name = path.replace(/\.(md|jmd)$/i, '');
	const base = name.split('/').pop();
	return `[[${resolve(base) === path ? base : name}#^${id}]]`;
}
